package com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify;
import com.bct.ngtpa.apiservice.application.dto.auth.login.account.*;import com.bct.ngtpa.apiservice.application.dto.auth.otp.*;import com.bct.ngtpa.apiservice.application.dto.session.authflow.*;import com.bct.ngtpa.apiservice.application.port.in.VerifyLoginOtpUseCase;import com.bct.ngtpa.apiservice.application.port.out.*;import com.bct.ngtpa.apiservice.application.usecase.auth.login.account.*;import com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.*;import java.time.*;import java.util.*;import reactor.core.publisher.Mono;
public final class LoginOtpVerifyService implements VerifyLoginOtpUseCase {private final LoginProtectedAuthFlowContextLoader loader;private final OtpChallengePort otp;private final LoginOtpVerifiedSessionPort verifiedSession;private final AuthFlowSessionCancellationPort cancellation;private final GetLoginAccountsUseCase accountLookup;private final LoginAccountRecordValidationService accountValidation;private final LoginAccountReferenceAssignmentService accountAssignment;private final Clock clock;public LoginOtpVerifyService(LoginProtectedAuthFlowContextLoader l,OtpChallengePort o,LoginOtpVerifiedSessionPort v,AuthFlowSessionCancellationPort c,GetLoginAccountsUseCase g,LoginAccountRecordValidationService validation,LoginAccountReferenceAssignmentService assignment,Clock k){loader=Objects.requireNonNull(l);otp=Objects.requireNonNull(o);verifiedSession=Objects.requireNonNull(v);cancellation=Objects.requireNonNull(c);accountLookup=Objects.requireNonNull(g);accountValidation=Objects.requireNonNull(validation);accountAssignment=Objects.requireNonNull(assignment);clock=Objects.requireNonNull(k);}public Mono<VerifyLoginOtpResult> verify(VerifyLoginOtpCommand c){return loader.load(new LoginProtectedAuthFlowContextCommand(c.authFlowSessionId(),c.csrfToken(),c.origin(),c.referer(),c.correlationId(),AuthFlowStatus.OTP_SENT,true)).flatMap(x->x.isValid()?verifyActive(c,x):Mono.just(result(VerifyLoginOtpStatus.AUTH_FLOW_INVALID,null,false))).onErrorReturn(result(VerifyLoginOtpStatus.SYSTEM_FAILED,null,false));}private Mono<VerifyLoginOtpResult> verifyActive(VerifyLoginOtpCommand c,LoginProtectedAuthFlowContextResult x){return otp.verifyChallenge(new VerifyOtpChallengeCommand(x.activeOtpChallengeId(),c.otpCode(),clock.instant())).flatMap(r->switch(r.outcome()){case VALID->verifiedSession.markVerified(c.authFlowSessionId(),c.correlationId()).then(Mono.defer(()->continueToAccounts(c,x)));case INVALID->Mono.just(result(VerifyLoginOtpStatus.INVALID,r.remainingAttempts(),false));case EXPIRED->Mono.just(result(VerifyLoginOtpStatus.EXPIRED,null,false));case LOCKED->cancellation.cancel(new AuthFlowSessionId(c.authFlowSessionId()),AuthFlowSessionCancellationReason.SECURITY_REJECTION,clock.instant()).thenReturn(result(VerifyLoginOtpStatus.VERIFY_ATTEMPTS_EXCEEDED,0,true));case ALREADY_VERIFIED->Mono.just(result(VerifyLoginOtpStatus.ALREADY_VERIFIED,null,false));default->Mono.just(result(VerifyLoginOtpStatus.AUTH_FLOW_INVALID,null,false));});}private Mono<VerifyLoginOtpResult> continueToAccounts(VerifyLoginOtpCommand c,LoginProtectedAuthFlowContextResult x){var context=x.context();return accountLookup.getAccounts(new GetLoginAccountsCommand(context.normalizedUsername(),context.custType(),c.correlationId())).map(auth->{if(auth.status()==LoginAccountAuthorizationStatus.UNAVAILABLE)return result(VerifyLoginOtpStatus.ACCOUNT_LIST_UNAVAILABLE,null,false);var validated=accountValidation.validate(auth.accounts());if(validated.status()==LoginAccountValidationStatus.ZERO_VALID_RECORDS)return result(VerifyLoginOtpStatus.ZERO_VALID_ACCOUNTS,null,false);var assigned=accountAssignment.assign(validated.accounts());return new VerifyLoginOtpResult(VerifyLoginOtpStatus.ACCOUNTS_READY,null,false,assigned.accounts());});}private VerifyLoginOtpResult result(VerifyLoginOtpStatus s,Integer remaining,boolean clear){return new VerifyLoginOtpResult(s,remaining,clear,List.of());}}
